payload.wgsl:
// Adapted from a Shadertoy heart-outline study — heart curve by
// Inigo Quilez, improved by Dave_Hoskins; audio-reactive pulse → sine.
const OPACITY = 0.9;
const PULSE_SPEED = 1.8;
const PI = 3.14159265;

// heart(p) = 0 traces a heart-shaped curve (x² + (1.2y − √|x|)² − 1).
fn heartCurve(p0: vec2f) -> f32 {
  var p = p0;
  p.y += 0.6;
  let k = 1.2 * p.y - sqrt(abs(p.x) + 0.3);
  return p.x * p.x + k * k - 1.0;
}

// Central-difference gradient — turns the curve value into a screen distance.
fn heartGrad(p: vec2f) -> vec2f {
  let h = vec2f(0.01, 0.0);
  return vec2f(heartCurve(p + h.xy) - heartCurve(p - h.xy),
               heartCurve(p + h.yx) - heartCurve(p - h.yx)) / (2.0 * h.x);
}

// 1 on the outline, 0 elsewhere; line width scales with the pulse.
fn heartLine(p: vec2f, pulse: f32) -> f32 {
  let de = abs(heartCurve(p)) / length(heartGrad(p));
  let eps = (15.0 + pulse * 3.0) / bgResolution().x;
  return 1.0 - smoothstep(eps, 2.0 * eps, de);
}

fn hsv2rgb(c: vec3f) -> vec3f {
  let K = vec4f(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  let q = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(vec3f(1.0), clamp(q - vec3f(1.0), vec3f(0.0), vec3f(1.0)), c.y);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let res = bgResolution();
  let p = (uv - 0.5) * vec2f(1.0, res.y / res.x);
  let pulse = 0.35 + 0.25 * sin(time * PULSE_SPEED);

  var col = vec3f(0.0);
  var a = 0.0;
  for (var i = 0; i < 7; i++) {
    var hue: vec3f;
    var ang: f32;
    var offset: vec2f;
    var scale = 0.7;
    if (i == 0) {
      hue = vec3f(1.0, 0.3, 0.3);
      ang = -time * 0.3;
      offset = vec2f(cos(ang), sin(ang)) * 0.03;
    } else if (i == 1) {
      hue = vec3f(0.6, 0.6, 1.0);
      ang = PI - time * 0.3;
      offset = vec2f(cos(ang), sin(ang)) * 0.03;
    } else {
      hue = hsv2rgb(vec3f(f32(i) / 5.0 + time * 0.2, 0.4, 0.9));
      ang = PI * f32(i - 2) * (2.0 / 5.0) + time * 0.3;
      offset = vec2f(cos(ang), sin(ang)) * 0.2;
      scale = 0.3 + f32(i) * 0.05;
    }
    let q = (p + offset) / (scale * (1.0 + pulse * 0.3) * 0.8);
    let line = heartLine(q * 10.0, pulse);
    col += line * hue;
    a = max(a, line);
  }
  // Straight alpha: only the lines cover the background behind this layer.
  return vec4f(clamp(col, vec3f(0.0), vec3f(1.0)), a * OPACITY);
}

// Tunables — edit and ⌘⏎.
const RAIN_COLOR = vec3f(0.88, 0.94, 1.0);
const FAR_ALPHA = 0.24;        // the curtain BEHIND the cast
const NEAR_ALPHA = 0.52;       // and the one in front, which has a lit face to
                               // read against rather than a dark background
const SPEED = 2.3;
const SLANT = 0.12;     // sideways drift
const AMOUNT = 0.55;    // 0..1 — fraction of columns raining
// How far out each curtain hangs, in the scene's own units. A character stands
// around 25 away, so one curtain is BEHIND the cast and one is in front — which
// is the whole point of a foreground. The far drops are cut off by the
// silhouette; the near ones pass over it.
const FAR_DIST = 30.0;
const NEAR_DIST = 8.0;
const SOFT = 0.6;       // feather at the silhouette, so the cut isn't a jagged edge

fn rnHash(x: f32) -> f32 {
  return fract(sin(x * 127.1) * 43758.5453);
}

fn rainLayer(p0: vec2f, time: f32, scale: f32, speed: f32) -> f32 {
  var p = p0;
  p.x += p.y * SLANT; // wind skew
  let q = vec2f(p.x * scale, p.y * scale * 0.14);
  let col = floor(q.x);
  let h = rnHash(col);
  if (h > AMOUNT) { return 0.0; }
  // Repeating fall coordinate, re-hashed EVERY cycle
  let fall = q.y + time * speed * (0.6 + 0.7 * h) + h * 9.0;
  let cyc = rnHash(col * 3.1 + floor(fall) * 7.7);
  let y = fract(fall);
  let len = 0.18 + 0.3 * cyc;
  let drop = smoothstep(len, 0.0, y) * smoothstep(0.0, 0.05, y);
  let cx = abs(fract(q.x) - 0.5 + (cyc - 0.5) * 0.3);
  return drop * smoothstep(0.09, 0.02, cx) * (0.35 + 0.65 * cyc);
}

// How much of a curtain hanging at `dist` survives at this pixel: all of it
// where the scene is farther away, none where the scene is nearer and therefore
// in front. Pixels the scene never drew read the far plane, so the open sky
// always takes rain.
fn curtain(dist: f32, depth: f32) -> f32 {
  return smoothstep(dist - SOFT, dist + SOFT, depth);
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = bgResolution();
  let p = vec2f(uv.x * res.x / res.y, uv.y);
  let far = FAR_ALPHA * rainLayer(p, time, 90.0, SPEED * 0.8) * curtain(FAR_DIST, depth);
  let near = NEAR_ALPHA * rainLayer(p + 2.3, time, 55.0, SPEED) * curtain(NEAR_DIST, depth);
  return vec4f(RAIN_COLOR, clamp(far + near, 0.0, 1.0));
}

// Tunables — edit and ⌘⏎.
const NEON_COLOR = vec3f(0.96, 0.45, 0.71);  // tube color (brand pink)
const NEON_COLOR_B = vec3f(0.45, 0.65, 0.98); // second hue the shimmer travels to
const GLOW = 0.8;                            // halo strength
const FLICKER = 0.1;                         // 0 = steady sign
const TEXT_SCALE = 0.075;                    // sign size on screen
const POS_Y = 0.24;                          // height above center

fn sdSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// "REZE DESIGN" as 40 pre-baked segments (glyph boxes 0..0.9 × 0..1, advance 1.2, word gap
fn sdText(p: vec2f) -> f32 {
  // Coarse reject: pixels far from the sign's bounding box skip the letters entirely (the halo
  let toBox = vec2f(max(abs(p.x - 6.20) - 6.20, 0.0), max(abs(p.y - 0.5) - 0.5, 0.0));
  let boxD = length(toBox);
  if (boxD > 1.0) { return boxD; }
  var d = 1e5;
  d = min(d, sdSegment(p, vec2f(0.0, 0), vec2f(0.0, 1)));
  d = min(d, sdSegment(p, vec2f(0.0, 1), vec2f(0.8, 1)));
  d = min(d, sdSegment(p, vec2f(0.8, 1), vec2f(0.8, 0.5)));
  d = min(d, sdSegment(p, vec2f(0.8, 0.5), vec2f(0.0, 0.5)));
  d = min(d, sdSegment(p, vec2f(0.4, 0.5), vec2f(0.9, 0)));
  d = min(d, sdSegment(p, vec2f(1.2, 0), vec2f(1.2, 1)));
  d = min(d, sdSegment(p, vec2f(1.2, 1), vec2f(2.1, 1)));
  d = min(d, sdSegment(p, vec2f(1.2, 0.5), vec2f(1.9, 0.5)));
  d = min(d, sdSegment(p, vec2f(1.2, 0), vec2f(2.1, 0)));
  d = min(d, sdSegment(p, vec2f(2.4, 1), vec2f(3.3, 1)));
  d = min(d, sdSegment(p, vec2f(3.3, 1), vec2f(2.4, 0)));
  d = min(d, sdSegment(p, vec2f(2.4, 0), vec2f(3.3, 0)));
  d = min(d, sdSegment(p, vec2f(3.6, 0), vec2f(3.6, 1)));
  d = min(d, sdSegment(p, vec2f(3.6, 1), vec2f(4.5, 1)));
  d = min(d, sdSegment(p, vec2f(3.6, 0.5), vec2f(4.3, 0.5)));
  d = min(d, sdSegment(p, vec2f(3.6, 0), vec2f(4.5, 0)));
  d = min(d, sdSegment(p, vec2f(5.5, 0), vec2f(5.5, 1)));
  d = min(d, sdSegment(p, vec2f(5.5, 1), vec2f(6.15, 1)));
  d = min(d, sdSegment(p, vec2f(6.15, 1), vec2f(6.4, 0.75)));
  d = min(d, sdSegment(p, vec2f(6.4, 0.75), vec2f(6.4, 0.25)));
  d = min(d, sdSegment(p, vec2f(6.4, 0.25), vec2f(6.15, 0)));
  d = min(d, sdSegment(p, vec2f(6.15, 0), vec2f(5.5, 0)));
  d = min(d, sdSegment(p, vec2f(6.7, 0), vec2f(6.7, 1)));
  d = min(d, sdSegment(p, vec2f(6.7, 1), vec2f(7.6, 1)));
  d = min(d, sdSegment(p, vec2f(6.7, 0.5), vec2f(7.4, 0.5)));
  d = min(d, sdSegment(p, vec2f(6.7, 0), vec2f(7.6, 0)));
  d = min(d, sdSegment(p, vec2f(8.8, 1), vec2f(7.9, 1)));
  d = min(d, sdSegment(p, vec2f(7.9, 1), vec2f(7.9, 0.5)));
  d = min(d, sdSegment(p, vec2f(7.9, 0.5), vec2f(8.8, 0.5)));
  d = min(d, sdSegment(p, vec2f(8.8, 0.5), vec2f(8.8, 0)));
  d = min(d, sdSegment(p, vec2f(8.8, 0), vec2f(7.9, 0)));
  d = min(d, sdSegment(p, vec2f(9.55, 0), vec2f(9.55, 1)));
  d = min(d, sdSegment(p, vec2f(11.2, 1), vec2f(10.3, 1)));
  d = min(d, sdSegment(p, vec2f(10.3, 1), vec2f(10.3, 0)));
  d = min(d, sdSegment(p, vec2f(10.3, 0), vec2f(11.2, 0)));
  d = min(d, sdSegment(p, vec2f(11.2, 0), vec2f(11.2, 0.45)));
  d = min(d, sdSegment(p, vec2f(11.2, 0.45), vec2f(10.8, 0.45)));
  d = min(d, sdSegment(p, vec2f(11.5, 0), vec2f(11.5, 1)));
  d = min(d, sdSegment(p, vec2f(11.5, 1), vec2f(12.4, 0)));
  d = min(d, sdSegment(p, vec2f(12.4, 0), vec2f(12.4, 1)));
  return d;
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let res = bgResolution();
  var p = (uv - 0.5) * vec2f(res.x / res.y, 1.0);
  p.y -= POS_Y;
  // The sign breathes and sways — quiet motion that says "live shader", not GIF.
  let wobble = 0.05 * sin(time * 0.9);
  let breathe = 1.0 + 0.05 * sin(time * 1.7);
  let c = cos(wobble);
  let si = sin(wobble);
  p = mat2x2f(c, -si, si, c) * p;
  // Screen space → text space (centered).
  let tp = p / (TEXT_SCALE * breathe) + vec2f(12.4 * 0.5, 0.5);
  let d = sdText(vec2f(tp.x, tp.y));

  // Neon = crisp tube + inner hot line + tight halo.
  let aa = fwidth(d) * 1.5;
  let tube = 1.0 - smoothstep(0.06 - aa, 0.06 + aa, d);
  let hot = 1.0 - smoothstep(0.02 - aa, 0.02 + aa, d);
  let core = tube * 0.75 + hot * 0.45;
  let halo = exp(-d * 5.0) * GLOW;
  // Gentle electrical shimmer (two incommensurate frequencies, shallow depth).
  let flicker = 1.0 - FLICKER * (0.5 + 0.5 * sin(time * 7.3) * sin(time * 3.1));
  let s = (core + halo) * flicker;

  // A hue gradient travels along the sign — the "this is a shader" tell.
  let hue = mix(NEON_COLOR, NEON_COLOR_B, 0.5 + 0.5 * sin(time * 1.1 + tp.x * 0.45));
  let color = hue + vec3f(0.35) * core; // core burns toward white
  return vec4f(clamp(color, vec3f(0.0), vec3f(1.0)), clamp(s, 0.0, 1.0));
}

// Tunables — edit a value and hit ⌘⏎ to see it live.
const TINT = vec3f(1.0, 0.96, 0.88);  // star color
const DENSITY = 0.5;                  // 0..1 — how crowded the sky is
const TWINKLE = 0.5;                  // 0..1 — flicker speed
const INTENSITY = 1.2;                // overall brightness

fn bgHash2(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

fn starLayer(sph: vec2f, scale: f32, thresh: f32, time: f32, speed: f32) -> f32 {
  let cell = floor(sph * scale);
  let h = bgHash2(cell);
  // Star sits at a hashed point inside its cell — kills the grid look.
  let local = fract(sph * scale) - (0.15 + 0.7 * h);
  let d = length(local);
  let bright = bgHash2(cell + 7.31).x;
  if (bright < thresh) { return 0.0; }
  // Per-star period from its own hash: some stars breathe over seconds, some blink quickly
  let period = 0.25 + 2.75 * bgHash2(cell + 31.7).y;
  let tw = 0.55 + 0.45 * sin(time * speed * period + h.x * 40.0);
  let size = (bright - thresh) / (1.0 - thresh);
  // Tight core + faint halo — a hard point of light, not a blurry blob.
  let r = 0.03 + 0.045 * size;
  let core = smoothstep(r, r * 0.25, d);
  let halo = smoothstep(r * 4.0, r, d) * 0.18;
  return (core + halo) * tw * (0.45 + 0.75 * size);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let d = normalize(ray);
  // Latitude/longitude projection
  let sph = vec2f(atan2(d.x, d.z) * 1.2, asin(clamp(d.y, -1.0, 1.0)) * 1.5);
  // Denser = MORE stars, not smaller ones (sizes untouched)
  let dens = mix(0.95, 0.82, clamp(DENSITY, 0.0, 1.0));
  var s = starLayer(sph, 30.0, dens, time, TWINKLE * 1.6);
  // Faint dust layer: denser, smaller, slower.
  s += 0.4 * starLayer(sph + 3.7, 70.0, mix(0.985, 0.9, clamp(DENSITY, 0.0, 1.0)), time, TWINKLE * 0.9);
  let a = clamp(s * INTENSITY, 0.0, 1.0);
  // Straight alpha — the engine's over-composite premultiplies.
  return vec4f(TINT, a);
}

// Fireworks — ported to WGSL from "Fireworks" by Gatomoi
// https://www.shadertoy.com/view/73sXWH
// The click-launched shells and the feedback trail are dropped: both needed
// extra buffers, and an effect here is a single pass.

// Tunables — edit and ⌘⏎.
const SHELLS = 8;              // shells in the rotation
const PARTICLES = 56;          // sparks per shell — THE cost dial
const SECONDARY = 4;           // crackles each qualifying spark throws
const PERIOD = 5.0;            // seconds between a slot's launches
// 0.382 of the period — the golden-ratio conjugate, kept in step with PERIOD. A
// rounder fraction resonates: were this an eighth of the period, slots 0 and 8
// would launch in lockstep and the sky would clump instead of filling.
const STAGGER = 1.91;          // seconds between one slot and the next
const CLIMB_SCALE = 1.6;       // stretches the climb only — a shell that shoots
                               // up instantly has no flight to watch
const SEQUENCE = 3.35;         // total life: climb + burst, and no longer — a slot
                               // past it is dead, so ending the window early is
                               // free frames
const BURST_TIME = 1.55;       // the reference's own burst length
// The reference's own value. Raising it was a mistake I made trying to force a
// visible fall — the fall is visible there because the trails DRAW it, not
// because the sparks drop harder, and a heavier one only made the burst hang
// below the point it went off at.
const GRAVITY = 0.32;
const CHILD_GRAVITY = 0.06;    // the same, for the embers
const CRACKLE_AT = 0.57;       // fraction of the burst before the secondaries go
const EXPOSURE = 1.52;
const SPEED = 0.85;            // clock multiplier — lower is slower, all of it
const BOOM = 0.95;             // how far the sparks throw — smaller sits further back
const LOW = 0.58;              // shells burst between LOW and HIGH up the frame
const HIGH = 0.9;
const CLIMB_TRAIL = 0.045;     // how much of the climb the rocket's streak covers.
                               // Small, because the climb is EASED: at 0.2 the
                               // rocket has already flown half its path, so that
                               // much of "its past" is half the frame.
const HEAD_HALO = 0.022;       // how far the rocket's own glow carries
const CLIMB_GLOW = 2.6;        // brightness of that streak. Brightness IS opacity
                               // here: the layer's alpha is its own energy, so a
                               // dim streak is a see-through one.
const CLIMB_HALO = 0.006;       // and how WIDE it is allowed to be. Brightness and
                               // width are separate dials on purpose — a 1/r glow
                               // spreads as you brighten it, so without a bound
                               // the only legible streak is a fat one.

// The reference kept its streaks in a buffer that decayed 0.955/0.925/0.875 per
// frame, so a streak lived about this long — and PER CHANNEL, blue fastest. Both
// numbers below are that buffer, solved rather than eyeballed: at 60fps the decay
// rates are ln(1/0.955)·60 = 2.76 for red against 8.0 for blue, so a 0.37s-old
// piece of streak keeps 36% of its red and 5% of its blue. That is why the tails
// go orange, and it is a colour we can compute instead of guess at.
const TRAIL_SECONDS = 0.37;
const TRAIL_DECAY = vec3f(2.76, 4.68, 8.0);
const TRAIL_MIX = 0.72;        // what the reference composited that buffer at
const PLAIN_SHELLS = 0.1;      // fraction that burst with no trails at all
const SMALLEST = 0.7;          // the runt of the rotation, as a fraction of BOOM

const TAU = 6.28318530718;
// Every 1/r glow inside the cull is faded to exactly zero at this radius, and the
// cull is this radius past the farthest spark. That makes the boundary a
// definition rather than an estimate: nothing can be truncated, because nothing
// is still alive out there. Estimating it is what drew the ring — a glow reads as
// visible far further than its raw value suggests, since the tone map lifts it
// (alpha = 1 − exp(−1.52·c)) before the frame is quantised.
// Derived, not chosen: a spark's glow is size·0.78/d, so at the size above it
// falls under one code value at 0.32. Every glow inside the cull is faded to
// zero exactly here, which is what makes the boundary safe to cull on.
const GLOW_REACH = 0.38;
// One 8-bit code value, referred back through the tone map (alpha = 1 − exp(−1.52·c)).
// Anything dimmer than this cannot change a pixel, so it need not be drawn.
const VISIBLE = 0.0026;

fn background(ray: vec3f, uv0: vec2f, clock: f32) -> vec4f {
  // One dial for the whole display: shells, climbs, bursts and the sparkle rate
  // all read this clock, so slowing it slows them together instead of drifting
  // out of step with each other.
  let time = clock * SPEED;
  let res = bgResolution();
  // Square units, y in −1..1, x carrying the aspect — the convention this came
  // from, and the one the ballistics constants are tuned in.
  let uv = vec2f((uv0.x * 2.0 - 1.0) * (res.x / max(res.y, 1.0)), uv0.y * 2.0 - 1.0);

  var col = vec3f(0.0);
  for (var s = 0; s < SHELLS; s++) {
    let slot = f32(s);
    let offset = slot * STAGGER;
    if (time < offset) {
      continue;
    }
    // Each slot fires on its own cycle; floor() names the launch, and every
    // random the shell wears is drawn from that name, so it keeps its colour and
    // its scatter for as long as it burns.
    let cycle = floor((time - offset) / PERIOD);
    let elapsed = time - (cycle * PERIOD + offset);
    if (elapsed <= 0.0 || elapsed >= SEQUENCE) {
      continue;
    }
    let seed = vec2f(slot * 91.7 + cycle * 17.3, cycle * 41.9 + slot * 8.2);
    col += fwSequence(uv, fwAutoTarget(slot, cycle, res), elapsed, seed, res) * 0.82;
  }

  let vignette = smoothstep(0.84, 0.2, length(uv0 - 0.5));
  col *= 0.9 + 0.1 * vignette;

  // A soft shoulder rather than a clamp: highlights roll off instead of clipping
  // flat to white, which is what keeps a bright core its own colour.
  let mapped = 1.0 - exp(-max(col, vec3f(0.0)) * EXPOSURE);
  let energy = max(max(mapped.r, mapped.g), mapped.b);
  if (energy <= 0.0) {
    return vec4f(0.0);
  }
  // Hue in rgb, energy in alpha: the composite does rgb·a + background·(1−a),
  // so this reads as additive light while embers still let the sky through.
  return vec4f(mapped / energy, energy);
}

// Climb, then burst. One shell is only ever doing one of the two.
fn fwSequence(uv: vec2f, targetPixel: vec2f, elapsed: f32, seed: vec2f, res: vec2f) -> vec3f {
  let climb = (0.9 + fwHash(seed + vec2f(45.0, 12.0)) * 0.18) * CLIMB_SCALE;
  if (elapsed < climb) {
    return fwRocket(uv, targetPixel, elapsed / climb, seed, res);
  }
  let t = (elapsed - climb) / BURST_TIME;
  if (t < 1.0) {
    return fwBurst(uv, fwToWorld(targetPixel, res), t, seed);
  }
  return vec3f(0.0);
}

// ── The climb ──

fn fwRocket(uv: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f) -> vec3f {
  let startPixel = fwLaunchPixel(targetPixel, seed, res);
  let pos = fwRocketPos(startPixel, targetPixel, t, seed, res);
  // Where it was an instant ago: the streak is the segment between the two, which
  // is the only trail we get in a single pass — the original accumulated one in a
  // feedback buffer.
  let prev = fwRocketPos(startPixel, targetPixel, max(t - CLIMB_TRAIL, 0.0), seed, res);

  let tint = normalize(fwPalette(seed) + vec3f(1.0, 0.72, 0.35));
  // The head needs its own bound for the same reason the streak does: at this
  // amplitude a bare 1/r stays above one code value two whole screen-heights
  // out, so the rocket dragged a frame-sized smudge around with it. Bounded, it
  // is a point with a small halo.
  let hd = length(uv - pos);
  let head = (0.0022 / (hd + 0.0011) * smoothstep(HEAD_HALO, 0.0, hd) +
              exp(-hd * hd * 55000.0) * 1.7);

  // The streak gets a hard core as well as a glow, for the same reason the
  // sparks do: a glow alone is a smudge, and it is the core that reads as a
  // line. `age` is 0 at the far end, so the streak thins and dims backwards
  // instead of ending square.
  let arc = fwArc(uv, prev, pos);
  // Holds full strength for the first third of the climb rather than starting to
  // go immediately, so the streak is still legible when the shell is high.
  let fadeIn = smoothstep(1.3, 0.35, t);
  let taper = mix(0.55, 1.0, arc.y);
  // The halo is faded to nothing at CLIMB_HALO, so the streak has an actual
  // edge; the core carries the light. Roughly three pixels wide at 1080p, which
  // is a wire rather than a band.
  let glow = 0.0014 / (arc.x + 0.0016) * smoothstep(CLIMB_HALO, 0.0, arc.x) *
             fadeIn * taper * CLIMB_GLOW;
  // 260000 against the head's 55000: the streak's falloff is a bit over half the
  // head's width, so the rocket reads as a point DRAGGING a wire rather than a
  // wire with a bulge in it. They were within 10% of each other before.
  let core = exp(-arc.x * arc.x * 260000.0) * 2.2 * fadeIn * taper * CLIMB_GLOW;

  return tint * head + mix(tint, vec3f(1.0, 0.38, 0.12), 0.35) * (glow + core);
}

fn fwRocketPos(startPixel: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f) -> vec2f {
  // Eased so it leaves fast and arrives slow, the way a shell running out of
  // thrust does. A FOURTH power, not a cube: it puts the rocket within a fraction
  // of a percent of its apex by four-fifths of the climb, so the last stretch is
  // a hang rather than an arrival. Without that pause the burst reads as going
  // off mid-flight — there is no moment of being at the top to go off AT.
  let x = clamp(t, 0.0, 1.0);
  let inv = 1.0 - x;
  let inv2 = inv * inv;
  var p = mix(fwToWorld(startPixel, res), fwToWorld(targetPixel, res), 1.0 - inv2 * inv2);
  // A little lateral bow, biggest mid-flight.
  p.x += sin(t * 3.14159265359) * (fwHash(seed + vec2f(17.0, 91.0)) - 0.5) * 0.055;
  return p;
}

fn fwLaunchPixel(targetPixel: vec2f, seed: vec2f, res: vec2f) -> vec2f {
  let offset = (fwHash(seed + vec2f(31.0, 4.0)) - 0.5) * res.x * 0.18;
  // Starts below the frame, so the pad itself is never on screen.
  return vec2f(clamp(targetPixel.x + offset, res.x * 0.06, res.x * 0.94), -res.y * 0.08);
}

// ── The burst ──

fn fwBurst(uv: vec2f, center: vec2f, t: f32, seed: vec2f) -> vec3f {
  // Nothing in this shell reaches farther than its fastest spark, plus the
  // crackles it throws, plus the distance a glow stays visible. Outside that
  // circle the loop below cannot contribute, so it is skipped whole — and a young
  // shell is nearly a point, which is when the saving is largest.
  let rel = uv - center;
  // Not every shell is the same shell: the small ones read as further away and
  // give the big ones something to be big against.
  let boom = BOOM * mix(SMALLEST, 1.0, fwHash(seed + vec2f(5.5, 2.2)));

  // The opening flash is a 1/r glow, so it reaches much further than the sparks
  // early on and nothing at all once it has decayed — its radius is derived
  // rather than guessed: the distance at which it falls under one code value.
  let flashAmp = exp(-t * 18.0) * 0.010;
  let flashReach = max(flashAmp / VISIBLE, 1e-4);

  // ONE test for the whole shell, against whichever of the two is currently
  // larger. Returning here costs a pixel nothing at all — not even the palette,
  // which is four hashes and two normalises that most pixels have no use for.
  let reach = max(flashReach,
                  (1.02 * t + 0.16 + 0.5 * GRAVITY * t * t + CHILD_GRAVITY) * boom + GLOW_REACH);
  if (dot(rel, rel) > reach * reach) {
    return vec3f(0.0);
  }

  let tint = fwPalette(seed);
  let flashDistance = length(rel);
  var col = normalize(tint + vec3f(1.0)) * flashAmp / (flashDistance + 0.0025) *
            smoothstep(flashReach, 0.0, flashDistance);

  let emberTint = normalize(tint + vec3f(0.9, 0.55, 0.25));
  let hotTint = normalize(tint + vec3f(1.0, 0.62, 0.22));
  // A tenth of shells burst with no streaks at all, which is what keeps the sky
  // from reading as one firework repeated.
  let trails = fwHash(seed + vec2f(101.7, 53.3)) >= PLAIN_SHELLS;
  // The streak's span in burst-time: one unit of t is BURST_TIME/SPEED seconds.
  let trailLen = select(0.0, TRAIL_SECONDS * SPEED / BURST_TIME, trails);
  let hSeed = fwHash(seed);

  let fade = smoothstep(0.82, 0.08, t);
  // The streaked layer outlives the sharp one and ramps in over the first frames
  // rather than arriving whole — both straight from the reference's second pass.
  let trailFade = smoothstep(0.95, 0.08, t) * smoothstep(0.0, 0.06, t);
  let crackleT = clamp((t - CRACKLE_AT) / (1.0 - CRACKLE_AT), 0.0, 1.0);

  // Radii for the rejects in the loop, hoisted — the same for every spark in the
  // shell. A spark's arc is no longer than its top speed plus gravity over the
  // streak's span; its embers stay within their own scatter.
  let sparkReach = (1.02 + GRAVITY) * boom * trailLen + GLOW_REACH;
  let emberReach = (0.16 + CHILD_GRAVITY) * boom + GLOW_REACH;

  for (var particle = 0; particle < PARTICLES; particle++) {
    let i = f32(particle);
    // An even fan, jittered, so the shell is round without being a stencil.
    let angle = i * (TAU / f32(PARTICLES)) + (fwHash(seed + vec2f(i, 13.1)) - 0.5) * 0.22;
    let velocity = vec2f(cos(angle), sin(angle)) * ((0.3 + 0.72 * fwHash(vec2f(i, hSeed))) * boom);

    let pos = fwBallistic(center, velocity, t, boom);

    // A pixel further from the spark than its whole arc plus a glow's reach
    // cannot be lit by any part of it. Skipping here skips the second ballistic,
    // the segment solve and all the shading — and a shell's sparks fan out over
    // ten times a glow's radius, so nearly all of them miss any given pixel.
    let toSpark = uv - pos;
    if (dot(toSpark, toSpark) <= sparkReach * sparkReach) {
      let sparkle = sin(t * 58.0 + i + hSeed * 12.0) * 0.5 + 0.5;

      // ── The sharp spark. Every one of them, drawn at where it IS. Gated on its
      // OWN radius, which is tighter than the reject above: that one has to cover
      // the streak's whole length, so between the two radii this maths would run
      // only to be multiplied by a window of zero.
      let d = length(toSpark);
      if (d < GLOW_REACH) {
        let size = 0.00125 * fade * (0.55 + 0.45 * sparkle);
        let glow = size / (d + 0.00062) * smoothstep(GLOW_REACH, 0.0, d);
        let core = exp(-d * d * 120000.0) * 1.35 * fade * (0.75 + 0.25 * sparkle);
        col += tint * (glow * 0.78 + core);
      }

      // ── The streak. EVERY OTHER spark, exactly as the reference's second pass
      // stepped its particle index by two: half the shell streaks and half stays
      // sharp, and it is the mixture that reads as fireworks rather than as a
      // net. Drawing it on all of them was what made the sky look woven.
      if (trails && (particle & 1) == 0) {
        let prev = fwBallistic(center, velocity, max(t - trailLen, 0.0), boom);
        // .x = distance to the arc, .y = where along it — 0 at the tail, 1 at
        // the spark. The second is the streak's own age, in seconds.
        let arc = fwArc(uv, prev, pos);
        let td = arc.x;
        if (td < GLOW_REACH) {
          // The decay the buffer applied over frames, applied over LENGTH
          // instead. Per channel, so the tail goes orange on its own rather than
          // being tinted orange by hand.
          let held = exp(-TRAIL_DECAY * ((1.0 - arc.y) * TRAIL_SECONDS));
          let tSize = 0.00105 * trailFade * (0.6 + 0.4 * sparkle);
          let tGlow = tSize / (td + 0.00072) * smoothstep(GLOW_REACH, 0.0, td);
          let tCore = exp(-td * td * 95000.0) * trailFade * (0.65 + 0.35 * sparkle);
          col += mix(tint, hotTint, 0.28 + sparkle * 0.2) * held *
                 (tGlow * 0.52 + tCore * 0.46) * TRAIL_MIX;
        }
      }
    }

    // Roughly two in five sparks crackle into a handful of embers. Tested
    // separately from the spark above, and NOT skipped with it: a crackle goes
    // off where the spark was at CRACKLE_AT, which by now is somewhere else
    // entirely.
    if (crackleT > 0.0 && fwHash(seed + vec2f(i, 71.7)) >= 0.58) {
      let origin = fwBallistic(center, velocity, CRACKLE_AT, boom);
      let toOrigin = uv - origin;
      if (dot(toOrigin, toOrigin) > emberReach * emberReach) {
        continue;
      }
      let flashDist = length(toOrigin);
      col += emberTint * exp(-crackleT * 20.0) * 0.0032 / (flashDist + 0.0018) *
             smoothstep(GLOW_REACH, 0.0, flashDist);

      for (var child = 0; child < SECONDARY; child++) {
        let j = f32(child);
        let cSeed = fwHash(seed + vec2f(i * 17.0, j * 23.0));
        let cAngle = TAU * (j / f32(SECONDARY) + cSeed * 0.35);
        let cVel = vec2f(cos(cAngle), sin(cAngle)) *
                   ((0.06 + 0.10 * fwHash(seed + vec2f(j * 9.0, i * 5.0))) * boom);

        var cPos = origin + cVel * crackleT;
        cPos.y -= CHILD_GRAVITY * boom * crackleT * crackleT;

        let cd = length(uv - cPos);
        let cFade = smoothstep(1.0, 0.05, crackleT);
        col += mix(emberTint, vec3f(1.0, 0.82, 0.42), cSeed * 0.45) *
               ((0.00088 * cFade) / (cd + 0.00062) * 0.75 * smoothstep(GLOW_REACH, 0.0, cd) +
                exp(-cd * cd * 150000.0) * 0.85 * cFade);
      }
    }
  }

  return col;
}

fn fwBallistic(center: vec2f, velocity: vec2f, t: f32, boom: f32) -> vec2f {
  // Gravity scales with the shell alongside the velocity it fights. Throwing the
  // sparks half again as far while they still drop the same 0.15 flattens every
  // arc into a straight fan — the trajectory has to grow with the shell, or the
  // shell stops falling.
  return center + velocity * t - vec2f(0.0, 0.5 * GRAVITY * boom * t * t);
}

// ── Toolbox ──

fn fwAutoTarget(slot: f32, cycle: f32, res: vec2f) -> vec2f {
  let seed = vec2f(slot * 37.17 + cycle * 11.31, cycle * 23.73 + slot * 5.91);
  return vec2f(
    mix(0.16, 0.84, fwHash(seed + vec2f(1.0, 0.0))),
    mix(LOW, HIGH, fwHash(seed + vec2f(0.0, 1.0))),
  ) * res;
}

/** Pixels → the square, y-normalised space everything above is tuned in. */
fn fwToWorld(pixel: vec2f, res: vec2f) -> vec2f {
  return (pixel * 2.0 - res) / max(res.y, 1.0);
}

fn fwPalette(seed: vec2f) -> vec3f {
  var base = vec3f(
    fwHash(seed + vec2f(11.3, 0.7)),
    fwHash(seed + vec2f(2.1, 19.8)),
    fwHash(seed + vec2f(7.6, 4.4)),
  );
  // +0.35 before normalising keeps any shell from coming out near-black.
  base = normalize(base + 0.35);
  let toward = mix(vec3f(1.0, 0.55, 0.18), vec3f(0.25, 0.55, 1.0), fwHash(seed + vec2f(8.0, 3.0)));
  return normalize(mix(base, toward, 0.35));
}

/** Distance to the segment ab — the rocket's streak. */
fn fwSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  return fwArc(p, a, b).x;
}

/** Distance to segment ab, and how far along it the nearest point sits (0 at a,
 *  1 at b). A spark's streak needs both: the distance draws it, the position
 *  along it ages it. */
fn fwArc(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 0.00001), 0.0, 1.0);
  return vec2f(length(pa - ba * h), h);
}

fn fwHash(p0: vec2f) -> f32 {
  var p = fract(p0 * vec2f(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// Tunables — edit and ⌘⏎.
const FOG_COLOR = vec3f(0.76, 0.80, 0.87);
const TOP = 13.0;        // how high the bank stands where it is thickest
const BODY = 0.5;        // fraction of that depth held at full density
const POOL = 62.0;       // how far out it pools around the scene's centre
const DENSITY = 0.05;    // extinction per world unit travelled through it
const DRIFT = 0.22;      // how fast it crawls
const SCALE = 0.038;     // size of the lumps
const START = 4.0;       // no fog closer than this, so the lens is never inside it
const STEPS = 18;        // samples along the ray — the cost dial
const FAR_CLAMP = 400.0;

// Mist as a VOLUME, integrated along the view ray — not a density sampled where
// the scene happens to be.
//
// Reading the depth once and shading that point can only ever produce a function
// of the surface's position, which is a texture painted on the floor: it cannot
// know about the air in FRONT of the character, so it can never wrap around one.
// Walking the ray and accumulating what it passes through is the whole
// difference, and it is what makes the bank something the cast stands inside
// rather than something they stand on.
fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let dir = normalize(ray);
  let cam = bgCameraPos();

  // How far along the ray the scene is. bgWorldPos already turns the view-axis
  // depth into a world point, so the distance between them is what we need.
  let tScene = length(bgWorldPos(ray, min(depth, FAR_CLAMP)) - cam);

  // Only the stretch that can be inside the slab is worth walking. Solving it
  // against the two horizontal planes means a ray aimed at the sky leaves at
  // once instead of marching through empty air to find nothing.
  let ceilMax = TOP * 1.55;
  var tEnter = START;
  var tExit = min(tScene, FAR_CLAMP);
  if (abs(dir.y) > 1e-4) {
    let ta = (0.0 - cam.y) / dir.y;
    let tb = (ceilMax - cam.y) / dir.y;
    tEnter = max(tEnter, min(ta, tb));
    tExit = min(tExit, max(ta, tb));
  } else if (cam.y < 0.0 || cam.y > ceilMax) {
    return vec4f(0.0);
  }
  // Horizontal bound. The pool is a CYLINDER, so solve the ray against it and
  // walk only the crossing — at most its diameter, however far the scene behind
  // it happens to be. This is what fixes the grain and the seam, and they were
  // the same fault: a span running to the far clamp made each step ~28 units,
  // wider than the lumps themselves, so the integral was being guessed at. And
  // where a ray stopped on the ground instead of reaching the sky, the step
  // length jumped, so the guess jumped with it — a horizon-shaped crack.
  let originXZ = cam.xz;
  let dirXZ = dir.xz;
  let a = dot(dirXZ, dirXZ);
  if (a < 1e-8) {
    // Straight up or down: inside the pool only if the camera is over it.
    if (dot(originXZ, originXZ) > POOL * POOL) {
      return vec4f(0.0);
    }
  } else {
    let b = dot(originXZ, dirXZ);
    let c = dot(originXZ, originXZ) - POOL * POOL;
    let disc = b * b - a * c;
    // A ray that never crosses the pool is done here, whatever it is looking at.
    if (disc <= 0.0) {
      return vec4f(0.0);
    }
    let root = sqrt(disc);
    tEnter = max(tEnter, (-b - root) / a);
    tExit = min(tExit, (-b + root) / a);
  }
  if (tExit <= tEnter) {
    return vec4f(0.0);
  }

  let span = tExit - tEnter;
  let stepLen = span / f32(STEPS);
  // A per-pixel offset into the first step. Fixed for a given pixel, so it reads
  // as fine grain rather than as flicker, and it breaks up the banding an evenly
  // sampled march otherwise lays down in slabs.
  let jitter = fogHash(uv * 1024.0);

  let flow = vec2f(time * DRIFT, time * DRIFT * 0.45);
  let flowFine = vec2f(time * DRIFT * 0.35, time * DRIFT * 0.62);

  var optical = 0.0;
  for (var i = 0; i < STEPS; i++) {
    let p = cam + dir * (tEnter + (f32(i) + jitter) * stepLen);

    // Around the cast, not across the world.
    let pool = 1.0 - smoothstep(POOL * 0.45, POOL, length(p.xz));
    if (pool <= 0.0) {
      continue;
    }

    // Two layers shearing against each other — one alone slides past as a sheet.
    let coarse = fogNoise(p.xz * SCALE + flow);
    let fine = fogNoise(p.xz * SCALE * 3.1 - flowFine);
    let lumps = mix(coarse, fine, 0.55);

    // Solid through its lower half, then thinning into a ceiling the lumps raise
    // and lower — so the bank has a surface, with wisps standing off it.
    let ceiling = TOP * (0.45 + 1.1 * lumps);
    let body = 1.0 - smoothstep(ceiling * BODY, ceiling, max(p.y, 0.0));
    // A floor under the lumps as well as a scale on them: at 0.4 the thin
    // patches thinned to nearly clear, which reads as gaps in the bank rather
    // than as variation within it.
    optical += body * pool * (0.6 + 0.7 * lumps);
  }

  // Beer–Lambert: what the ray actually lost crossing all of that. Depth through
  // the bank IS the opacity, which is why it thickens toward the far side of the
  // pool without any distance term — and why a character standing in it is veiled
  // by the air in front of them rather than tinted by the floor behind them.
  let alpha = 1.0 - exp(-optical * stepLen * DENSITY);
  if (alpha <= 0.0) {
    return vec4f(0.0);
  }
  return vec4f(FOG_COLOR, clamp(alpha, 0.0, 1.0));
}

// ── Toolbox ──

fn fogHash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

/** Value noise, 0..1. */
fn fogNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(fogHash(i), fogHash(i + vec2f(1.0, 0.0)), u.x),
    mix(fogHash(i + vec2f(0.0, 1.0)), fogHash(i + vec2f(1.0, 1.0)), u.x),
    u.y,
  );
}

// Tunables — edit and ⌘⏎.
const RIPPLE_COLOR = vec3f(0.72, 0.86, 1.0);
const WAVELENGTH = 2.6;    // world units between crests
const SPEED = 0.9;         // crests per second travelling outward
const REACH = 9.0;         // how far from the feet the rings still read
const RINGS = 0.55;        // crest sharpness — higher is tighter, more like water
const LIFT = 1.2;          // fades out this far above the floor
const STRENGTH = 0.55;
const STAND_Y = 10.0;      // センター's height on a standing MMD model
const AIRBORNE = 6.0;      // rings fade out over this much jump height
const FAR_CLAMP = 400.0;

// Rings on the floor, centred on whoever is standing there.
//
// The ray and the depth describe the PIXEL; they cannot say where anybody is.
// bgSubjectPos does, so the shape can be a function of the distance from a
// character's feet rather than of screen position — which is the difference
// between an effect that decorates the frame and one that responds to the cast.
// Walk it: the rings follow.
//
// A PMX model's root sits between the feet on the floor, so the subject position
// is already the contact point. Nothing to offset.
fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  // Where the scene drew this pixel. A floor effect has to know where the floor
  // is, and depth alone only says how far away something was.
  let world = bgWorldPos(ray, min(depth, FAR_CLAMP));

  // Nothing was drawn here, or it was drawn a long way off: no floor to ring.
  if (depth >= FAR_CLAMP) {
    return vec4f(0.0);
  }

  // Only near the floor. This is also what keeps the rings off the character —
  // they are a metre and a half of geometry standing above the plane the effect
  // lives on, so height alone excludes them without a mask.
  let height = clamp(1.0 - world.y / LIFT, 0.0, 1.0);
  if (height <= 0.0) {
    return vec4f(0.0);
  }

  var wave = 0.0;
  let n = bgSubjectCount();
  for (var i = 0; i < n; i = i + 1) {
    let feet = bgSubjectPos(i);
    // Distance along the FLOOR, so a tall character rings the same as a short
    // one and the rings stay circular rather than stretching with height.
    let d = distance(world.xz, feet.xz);
    if (d > REACH) {
      continue;
    }

    // The subject position carries HEIGHT too, and センター rises when a motion
    // leaves the floor — so a jump lifts the character out of the water and the
    // rings go with them, instead of a puddle following someone through the air.
    let airborne = clamp((feet.y - STAND_Y) / AIRBORNE, 0.0, 1.0);
    let grounded = 1.0 - airborne * airborne;

    // Outward-travelling crests, thinned to rings rather than a sine hill, and
    // faded with distance so the pattern has an edge instead of tiling forever.
    let phase = d / WAVELENGTH - time * SPEED;
    let crest = pow(max(sin(phase * 6.2831853), 0.0), 1.0 / RINGS);
    let falloff = 1.0 - d / REACH;
    wave = wave + crest * falloff * falloff * grounded;
  }

  let a = clamp(wave * STRENGTH * height, 0.0, 1.0);
  return vec4f(RIPPLE_COLOR, a);
}

// @anchor 頭

// Tunables — edit and ⌘⏎.
const RING_COLOR = vec3f(1.0, 0.86, 0.42);   // the filament itself
const GLOW_COLOR = vec3f(1.0, 0.70, 0.28);   // the light it throws
const LIFT = 2.3;        // world units above the head bone
const FORWARD = 0.0;     // shift along the head's own facing, to centre it
const RADIUS = 1.75;     // world radius of the ring
const TUBE = 0.040;      // tube radius — the bright filament
const GLOW = 0.5;        // how far the light reaches beyond it, world units
const GLOW_STRENGTH = 0.5;
const SPIN = 0.35;       // turns per second, seen in the bright spot
const STEPS = 36;        // sphere-trace steps — a thinner tube needs more
// Nothing: the head BLOCKS the ring rather than showing it through.
const OCCLUDED = 0.0;

// A ring of light over every head — a real TORUS in the world.
//
// The worked example for rzAnchor: the head is a BONE, so the ring rides a nod
// and a lean the way an accessory parented to that bone would.
//
// WHY A TORUS AND NOT A DISC. The first version intersected the view ray with
// the ring's plane and measured distance in xz. That is a flat annulus: correct
// from above, and it collapses to nothing seen from the side, because a plane
// has no thickness. A halo seen edge-on should still be a bar of light — so this
// marches the torus's distance field instead and keeps the tube's own radius in
// every direction. It costs a short loop and it is the difference between a
// light and a decal.
//
// The falloff has compact support: smooth everywhere and exactly zero where the
// march stops looking. Fading with an exponential and then culling it leaves a
// hard-edged disc of haze — an earlier version of this file did precisely that.
fn sdTorus(p: vec3f) -> f32 {
  let q = vec2f(length(p.xz) - RADIUS, p.y);
  return length(q) - TUBE;
}

fn haloGlow(d: f32) -> f32 {
  let x = clamp(d / GLOW, 0.0, 1.0);
  let f = 1.0 - x;
  return f * f * f;
}

fn haloFor(subject: i32, ray: vec3f, origin: vec3f, depth: f32, time: f32) -> vec4f {
  let head = rzAnchor(subject, 0);
  // A rig that spells the head differently simply has no halo, rather than one
  // pinned to the world origin.
  if (!head.valid) { return vec4f(0.0); }

  var centre = head.pos + vec3f(0.0, LIFT, 0.0);
  // 頭 sits at the base of the skull, not at the middle of the head, so a ring
  // lifted straight up can read as sitting behind the crown. FORWARD nudges it
  // along the head's own facing; leave it at 0 for a rig where it already sits right.
  if (FORWARD != 0.0) { centre = centre + head.fwd * FORWARD; }

  // Sphere-trace the torus. The step is the distance field's own value, which
  // is a lower bound on the distance to the surface — so the march can never
  // step OVER the tube, however thin it is.
  //
  // Fixed steps cannot promise that, and the first version of this used twelve
  // of them across nearly four world units while the tube's radius was 0.075.
  // The march simply stepped past the ring almost everywhere and registered it
  // only where a sample happened to land on it, so the halo came out as a string
  // of disconnected beads. Anything thin sampled at a fixed rate does this.
  let oc = origin - centre;
  let bound = RADIUS + TUBE + GLOW;
  let b = dot(oc, ray);
  let disc = b * b - (dot(oc, oc) - bound * bound);
  if (disc < 0.0) { return vec4f(0.0); }   // the ray misses the ring entirely
  let sq = sqrt(disc);
  let tExit = -b + sq;
  if (tExit <= 0.0) { return vec4f(0.0); }  // the ring is behind the camera
  var t = max(-b - sq, 0.0);

  var best = 1e9;
  var bestT = t;
  for (var i = 0; i < STEPS; i++) {
    if (t > tExit) { break; }
    let dist = sdTorus(origin + ray * t - centre);
    if (dist < best) {
      best = dist;
      bestT = t;
    }
    if (dist < 0.0012) { break; }          // on the filament — close enough
    t += max(dist, 0.006);                 // floor, so a graze cannot stall
  }
  let d = max(best, 0.0);
  if (d > GLOW) { return vec4f(0.0); }

  // A thin bright filament inside a soft halo: the filament carries the shape,
  // the halo carries the light. Two terms are what keep a neon ring from reading
  // as a fat blurred donut.
  let filament = 1.0 - smoothstep(0.0, TUBE * 0.9, d);
  let glow = haloGlow(d) * GLOW_STRENGTH;
  let hit = origin + ray * bestT - centre;
  let ang = atan2(hit.z, hit.x);
  let spin = 0.82 + 0.18 * sin(ang - time * SPIN * 6.2831853);

  // The far side of the ring passes behind the head, and is simply not drawn
  // there — a halo you can see through the skull is a decal, not a light.
  if (bestT > depth) { return vec4f(0.0); }
  let alpha = clamp((filament + glow) * spin, 0.0, 1.0);
  // White-hot at the filament, warm in the haze — the colour shift is most of
  // what makes a light look bright rather than merely light-coloured.
  let rgb = mix(GLOW_COLOR, mix(RING_COLOR, vec3f(1.0), filament * 0.7), filament);
  return vec4f(rgb, alpha);
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let origin = rzCameraPos();
  let dir = normalize(ray);
  var acc = vec4f(0.0);
  for (var i = 0; i < rzSubjectCount(); i++) {
    let h = haloFor(i, dir, origin, depth, time);
    acc = vec4f(acc.rgb + h.rgb * h.a, acc.a + h.a);
  }
  let a = clamp(acc.a, 0.0, 1.0);
  if (a <= 0.001) { return vec4f(0.0); }
  return vec4f(acc.rgb / max(acc.a, 1e-4), a);
}

// @anchor 左手首 trail
// @anchor 右手首 trail

// Tunables — edit and ⌘⏎.
const CORE_COLOR = vec3f(0.86, 0.97, 1.0);   // white-hot, faintly blue
const BODY_COLOR = vec3f(0.10, 0.58, 1.0);   // electric azure
const HAZE_COLOR = vec3f(0.06, 0.26, 0.92);  // deep blue, in the outer light

const LIFETIME = 0.70;   // seconds of path drawn behind the hand
const WIDTH = 7.0;       // core half-width in pixels, at the hand
const TAIL_WIDTH = 0.40; // ...and at the far end, as a fraction of it
const TAIL_EASE = 0.22;  // last stretch of life spent fading to nothing
const GLOW = 34.0;       // soft halo radius in pixels
const CORE = 3.4;        // weight of the core — what makes it read as light
const BLOOM = 0.55;      // weight of the wide halo
const LIGHT = 1.35;      // final gain on the ribbon's alpha


// The height these pixel sizes were tuned at. Everything below measured in
// PIXELS is scaled by res.y / REF_H, because the editor's canvas and an export
// are not the same size: a 48px glow is a wide halo in a 1200px viewport and a
// thin line in a 4K frame, so an export came out looking like a different
// effect. Sizes derived from pxPerUnit need none of this — they are world
// measurements and already scale.
const REF_H = 1080.0;

const STRIDE = 1;        // every sample near the hand — see the loop
const MIN_SEG_PX = 0.7;  // below this the hand is not moving
const REF_SEG_PX = 13.0; // segment length counting as a full contribution

// Sparks thrown off the ribbon. Seeded on the path and then living their own
// life: orbiting it, widening away from it and rising, so they read as shed by
// the trail rather than printed along it.
//
// These distances are WORLD units, and the scale that matters is MMD's: a model
// stands about 20 units tall, so an orbit of 0.16 is roughly a centimetre —
// invisible, leaving every spark sitting on the path looking like a dot stuck to
// it. Judge these against the character's height, not against 1.0.
const SPARK_COLOR = vec3f(0.92, 0.99, 1.0);
const SPARK_EVERY = 1;    // emit a spark every N path samples
const SPARK_PER = 4;      // ...and this many at each, on different phases
// A spark must not outlive the ribbon that threw it. At 1.4s against a 0.70s
// LIFETIME, the tail of the trail had faded to nothing while its sparks were
// still at half brightness — bright dots strung along a trail that was no longer
// there, which is exactly what they looked like.
const SPARK_LIFE = 0.70;  // seconds a spark lasts — keep at or below LIFETIME
const SPARK_EMERGE = 0.30;// ...spent fading in, while it clears the ribbon
// WORLD units, not pixels. A size in pixels is the same size everywhere on
// screen however far away the spark is, which is why they read as a flat,
// evenly-sized dot pattern laid over the shot rather than as particles in the
// scene — nothing about them changes with distance, so the eye reads them as
// texture. pxPerUnit below turns this into pixels at the depth the spark
// actually is, so the far ones are small and the near ones are not.
const SPARK_SIZE = 0.085; // world units
const SPARK_MAX_PX = 5.5; // ...and never bigger than this on screen
const ORBIT_R = 0.9;      // world units it circles the path at, when new
const ORBIT_GROW = 1.8;   // ...and how fast that widens with age
const ORBIT_SPEED = 7.0;  // radians per second around the path
const RISE = 2.4;         // world units per second it drifts upward
const TWINKLE = 9.0;
const SPARKS = 2.6;

// A neon ribbon along the path each hand actually took.
//
// The worked example for rzTrail. A velocity is the difference between two
// frames, so a ribbon built from one shakes on every wobble and flips when a
// hand changes direction — and one segment cannot curve, which is what a dance
// trail is made of. rzTrail is the path itself, sampled at a fixed rate on the
// SCENE clock, so the ribbon is identical in the editor, in an export and in a
// re-export.
//
// FIVE THINGS WORTH STEALING, all of which any anchor-driven effect will hit:
//
// 1. COLOUR COMES FROM INTENSITY, not from age or position. An effect mount is
//    alpha-composited, not additive, so a saturated blue at half alpha blends
//    toward whatever is behind it and reads muddy. Light looks bright because it
//    goes WHITE where it is strong and keeps its colour only where it falls off.
//    Chasing brightness by saturating the blue does the opposite of what it
//    looks like it should.
//
// 2. WEIGHT BY LENGTH. This is a line integral along a path: a segment should
//    contribute in proportion to the path it covers. Summing segments unweighted
//    looks right while a hand moves and becomes a white ball the moment it
//    stops, because fifty samples land on one point.
//
// 3. SUM the segments, do not take the nearest — a polyline's distance field
//    creases wherever two segments meet, and a wide glow turns every crease into
//    a facet. And a falloff used with a CULL has to reach zero AT the cull;
//    exp() never does, so cutting it leaves a hard rim.
//
// 4. CULL against the PATH, not the character, and project the bound ONCE.
//    Every pixel in the frame pays for the cull whether or not it survives it.
//
// 5. OCCLUDE PER SEGMENT, at the nearest point on it. One depth for a whole
//    segment pops the segment on and off as a character turns, instead of
//    cutting the ribbon cleanly at the silhouette.
fn hash11(x: f32) -> f32 {
  return fract(sin(x * 127.1) * 43758.5453);
}

fn ribbonGlow(d: f32, glowPx: f32) -> f32 {
  let x = clamp(d / glowPx, 0.0, 1.0);
  let f = 1.0 - x;
  return f * f * f;
}

/** Distance to the segment, and WHERE along it the nearest point fell — the
 *  second value is what lets depth be interpolated to that exact point. */
fn segDistPx(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return vec2f(distance(pa, ba * h), h);
}

fn ribbonFor(subject: i32, slot: i32, px: vec2f, depth: f32, res: vec2f, time: f32) -> vec4f {
  // Every pixel measurement below, at this frame's size. NOT named k: the small
  // loops in here all count with k, and an i32 counter shadowing this silently
  // turns every scaled size into a type error at best.
  let pxK = res.y / REF_H;
  let glowPx = GLOW * pxK;
  let widthPx = WIDTH * pxK;
  let minSegPx = MIN_SEG_PX * pxK;
  let refSegPx = REF_SEG_PX * pxK;
  let n = rzTrailCount(subject, slot);
  if (n < 2) { return vec4f(0.0); }

  // ── The cull: four points spread along the path, bounded as a circle,
  // projected once and kept.
  var pts: array<vec2f, 4>;
  var ok: array<f32, 4>;
  var mid = vec2f(0.0);
  var seen = 0.0;
  for (var k = 0; k < 4; k++) {
    let q = rzProject(rzTrail(subject, slot, min(k * n / 3, n - 1)).xyz);
    // Behind the lens: RECORD that, do not just skip it. An unwritten var is
    // zero here, so a missing point reads as (0,0) — the corner of the screen —
    // which both paints a blob there and inflates the bound below.
    ok[k] = select(0.0, 1.0, q.z > 0.0);
    if (ok[k] < 0.5) { continue; }
    pts[k] = q.xy * res;
    mid += pts[k];
    seen += 1.0;
  }
  if (seen < 1.0) { return vec4f(0.0); }
  mid /= seen;
  var reach = 0.0;
  for (var k = 0; k < 4; k++) {
    if (ok[k] > 0.5) { reach = max(reach, distance(pts[k], mid)); }
  }
  // A wide GLOW is what makes this read as a light rather than a bright line,
  // and it has to come from the segment loop below. A cheap version that fell
  // off around four coarse samples of the path drew three straight chords
  // between them — at a hundred pixels wide, that is three glowing bars cutting
  // across the frame wherever the hand's path curved, which is most of the time.
  // There is no cheap approximation of a curve that is still a curve.
  //
  // It cannot come from the engine's bloom either: a foreground effect
  // composites AFTER tone mapping, so the bloom pyramid was built long before
  // this shader ran. An effect that wants to glow has to glow by itself.
  if (distance(px, mid) > reach * 1.5 + glowPx) { return vec4f(0.0); }

  // ── The ribbon.
  var core = 0.0;
  var halo = 0.0;
  var sparks = 0.0;

  var prevW = rzTrail(subject, slot, 0).xyz;
  var prevP = rzProject(prevW);
    // Progressive stride: every sample near the hand, where the ribbon is widest
    // and a chord would show as a corner; coarser down the tail, where it is thin
    // and fading and the saving is free.
    for (var i = STRIDE; i < n; i = i + select(STRIDE, STRIDE * 2, i * 3 > n)) {
      let cur = rzTrail(subject, slot, i);
      if (cur.w > LIFETIME) { break; }
      let curP = rzProject(cur.xyz);
      // BOTH ends in front of the lens: a point behind it projects to a uv that
      // means nothing, and one bad end would smear the segment across the frame.
      if (prevP.z > 0.0 && curP.z > 0.0) {
        let pa = prevP.xy * res;
        let pb = curP.xy * res;
        let segLen = distance(pa, pb);
        // Box reject: four comparisons instead of a distance function and two
        // exponentials, for the many segments nowhere near this pixel.
        let lo = min(pa, pb) - glowPx;
        let hi = max(pa, pb) + glowPx;
        let inBox = px.x >= lo.x && px.x <= hi.x && px.y >= lo.y && px.y <= hi.y;
        if (inBox && segLen >= minSegPx) {
          // The tail. `age` runs 1 at the hand to 0 at the end of LIFETIME; the
          // ribbon narrows toward TAIL_WIDTH along it and its brightness falls
          // faster than its width, so the trail thins into the dark rather than
          // stopping. TAIL_EASE spends the last stretch fading to nothing, or the
          // oldest sample would end the ribbon on a visible edge.
          let age = clamp(1.0 - cur.w / LIFETIME, 0.0, 1.0);
          let ease = smoothstep(0.0, TAIL_EASE, age);
          let bright = age * age * ease;
          let w = max(widthPx * mix(TAIL_WIDTH, 1.0, pow(age, 0.7)), 0.8 * pxK);
          let weight = clamp(segLen / refSegPx, 0.0, 1.0);

          let hit = segDistPx(px, pa, pb);
          let d = hit.x;
          // Depth AT the nearest point, so occlusion follows the geometry.
          let segZ = mix(prevP.z, curP.z, hit.y);
          if (d < glowPx && segZ <= depth) {
            // CORE takes the MAX, HALO takes the SUM, and the split matters.
            //
            // A pixel beside a joint is near TWO segments, so summing gives it
            // twice the light of a pixel mid-segment — a bright bead at every
            // sample, worst where the core is thin and the beads are all it has.
            // The core is a line and a line is the NEAREST distance to it, so max
            // is the honest operator there.
            //
            // The halo still sums, because that is what smooths the creases where
            // segments meet; those creases are invisible in a wide soft falloff
            // and glaring in a narrow bright one.
            core = max(core, exp(-(d * d) / (w * w)) * bright * weight);
            halo += ribbonGlow(d, glowPx) * bright * weight;
          }
        }
        // ── Sparks, shed at this sample and living their own life since.
        //
        // Placed WITHOUT a projection. The loop already knows this segment's
        // length in pixels and its endpoints in the world, and the ratio of the
        // two is the local pixels-per-world-unit — so a spark's orbit can be sized
        // correctly on screen from numbers already in hand. Projecting each one
        // was costing a full transform per spark per pixel, which is what kept
        // them sparse enough to read as scattered dots.
        let worldStep = distance(cur.xyz, prevW);
        let pxPerUnit = segLen / max(worldStep, 1e-5);
        if (i % SPARK_EVERY == 0 && cur.w < SPARK_LIFE && curP.z <= depth) {
          let age = cur.w;
          let fall = 1.0 - clamp(age / SPARK_LIFE, 0.0, 1.0);
          // Fade IN over the first stretch of life. A spark is born on the path,
          // and at full brightness there it is simply a bright dot sitting on the
          // ribbon — which is what they looked like. By the time it is visible it
          // has swung clear, so what you see is a spark leaving the trail rather
          // than one stuck to it.
          let emerge = smoothstep(0.0, SPARK_EMERGE, age);
          let rPx = ORBIT_R * (1.1 + age * ORBIT_GROW) * pxPerUnit;
          let risePx = age * RISE * pxPerUnit;
          for (var k = 0; k < SPARK_PER; k++) {
            let h = hash11(f32(i) * 3.7 + f32(k) * 19.3 + f32(slot) * 17.0 + f32(subject) * 53.0);
            let theta = h * 6.2831853 + age * ORBIT_SPEED;
            let sp = curP.xy * res + vec2f(cos(theta), sin(theta) * 0.75) * rPx + vec2f(0.0, risePx);
            let dd = distance(px, sp);
            // Clamped at BOTH ends. A world size is right for depth but a spark
          // close to the lens then balloons into a blob, which is worse than the
          // flat dots it replaced; and below a pixel it flickers as it crosses
          // the sampling grid rather than shrinking gracefully.
          let size = clamp(SPARK_SIZE * pxPerUnit * (0.5 + 0.9 * h), 0.75 * pxK, SPARK_MAX_PX * pxK);
            if (dd < size * 3.5) {
              let twinkle = 0.4 + 0.6 * sin(time * TWINKLE + h * 6.2831853);
              // A hard pinpoint inside a soft bloom — what makes a spark read as a
              // spark rather than a smudge.
              let soft = exp(-(dd * dd) / (size * size));
              let hot = exp(-(dd * dd) / (size * size * 0.16));
              sparks += (soft * 0.55 + hot) * fall * fall * twinkle * emerge;
            }
          }
        }
      }
    prevP = curP;
    prevW = cur.xyz;
  }

  // Intensity FIRST, colour from it. `heat` is the ribbon's own strength before
  // it is clamped into an alpha, which is what lets the core know it is a core.
  let heat = core * CORE + halo * BLOOM;
  let star = clamp(sparks * SPARKS, 0.0, 1.0);
  if (heat <= 0.004 && star <= 0.004) { return vec4f(0.0); }

  var rgb = mix(HAZE_COLOR, BODY_COLOR, smoothstep(0.03, 0.40, heat));
  rgb = mix(rgb, CORE_COLOR, smoothstep(0.45, 1.30, heat));
  rgb = mix(rgb, SPARK_COLOR, star);
  return vec4f(rgb, clamp(heat * LIGHT + star, 0.0, 1.0));
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let px = uv * res;
  var acc = vec4f(0.0);
  for (var i = 0; i < rzSubjectCount(); i++) {
    for (var t = 0; t < 2; t++) {
      let v = ribbonFor(i, t, px, depth, res, time);
      acc = vec4f(acc.rgb + v.rgb * v.a, acc.a + v.a);
    }
  }
  let a = clamp(acc.a, 0.0, 1.0);
  if (a <= 0.001) { return vec4f(0.0); }
  return vec4f(acc.rgb / max(acc.a, 1e-4), a);
}

// @anchor 左足ＩＫ trail
// @anchor 右足ＩＫ trail
// @anchor 左足首 trail
// @anchor 右足首 trail

// Tunables — edit and ⌘⏎.
// Colour comes from INTENSITY, not from a single tint. A disc filled with one
// saturated colour and then alpha-blended over a dark floor lands somewhere in
// the middle and reads muddy — which is how a red print came out dark orange.
// Light goes WHITE where it is strong and keeps its colour only as it falls off.
const HOT_COLOR = vec3f(0.88, 0.99, 1.0);    // white-cyan, centre of a fresh print
const GLOW_COLOR = vec3f(0.14, 0.76, 1.0);   // cyan, the body of it
const RIM_COLOR = vec3f(0.05, 0.30, 0.95);   // deep blue, at the edge
const RADIUS = 1.6;      // world units
const EDGE = 0.5;        // soft rim as a fraction of the radius
// How much the foot must have dropped for a sample to read as a landing. A
// RELATIVE test, never an absolute height: 足ＩＫ sits at the ANKLE, already a
// hand's width up on a bare foot and higher in heels, so any constant measured
// from the floor is wrong on some rig.
const TOUCH_EPS = 0.03;
const FADE = 2.0;        // seconds a print takes to burn out
const FLATNESS = 0.22;   // world units of ground the mark may lie on
// EVERY sample. The ring shifts by one each frame, so a given moment of the
// path sits on an even index one frame and an odd one the next — striding over
// it means a landing is detected every OTHER frame, and the print strobes at
// half the framerate. The body below is two reads and two compares until a
// landing is actually found, so visiting every index is cheap.
const STRIDE = 1;
const ELONGATE = 1.0;    // 1 = round; above 1 stretches along the step
const STRENGTH = 2.3;
const FAR_CLAMP = 400.0;

// Marks where the feet met the ground, left behind as the character walks away.
//
// The worked example for rzSubject().root and for reading a trail in WORLD space
// rather than on screen. It was called Footfalls and only lit the foot's current
// position, which followed the foot around like a spotlight — a foot's location,
// not a footprint.
//
// A print is a place and a TIME: born where the foot met the floor, then burning
// down while the foot walks on. rzTrail carries exactly that — every sample is a
// position plus how many seconds ago it was there — so the samples whose height
// is near the floor ARE the contacts, and their age is how long ago each one
// happened. That is a real print that stays behind, out of data the engine keeps
// for a hand ribbon.
//
// It is still an approximation of contact rather than the thing itself: engine
// contact events would give the exact frame a foot landed, its facing and how
// hard, where this infers it from height. Good enough to look right, and the
// comment is here so the next person knows which part is the stand-in.
//
// The height test is also why the band has to be tight: a shoe's toe is a few
// centimetres off the ground, so a generous band marks the toe as readily as the
// floor under it. Position alone cannot tell them apart — they are in the same
// place. Knowing which pixels are the CHARACTER would, and that needs the subject
// mask the engine does not expose yet.
fn markFor(subject: i32, slot: i32, alt: i32, p: vec3f) -> f32 {
  var n = rzTrailCount(subject, slot);
  var pick = slot;
  if (n < 2) {
    n = rzTrailCount(subject, alt);
    pick = alt;
  }
  if (n < 4) { return 0.0; }

  // Cull in world space: the whole walk fits in a circle, and most of the floor
  // is nowhere near it.
  var mid = vec2f(0.0);
  for (var k = 0; k < 4; k++) {
    mid += rzTrail(subject, pick, min(k * n / 3, n - 1)).xz;
  }
  mid *= 0.25;
  var reach = 0.0;
  for (var k = 0; k < 4; k++) {
    reach = max(reach, distance(rzTrail(subject, pick, min(k * n / 3, n - 1)).xz, mid));
  }
  if (distance(p.xz, mid) > reach * 1.5 + RADIUS) { return 0.0; }

  var acc = 0.0;
  for (var i = STRIDE; i + STRIDE < n; i = i + STRIDE) {
    let s = rzTrail(subject, pick, i);
    if (s.w > FADE) { break; }               // older than a print lasts

    // TOUCHDOWN, not "low". Index 0 is now and rising indices run backwards in
    // time, so `older` is where the foot was before this sample and `newer` is
    // where it went after. A landing is the moment it STOPS descending: it was
    // higher a moment ago, and it did not keep dropping.
    //
    // Marking every low sample instead — which is what this did — puts a print
    // every 20ms through the whole stance, forty overlapping discs that merge
    // into one blob and flicker as each new one is born a few centimetres from
    // the last. A step should leave ONE print, and the path already says
    // exactly when it happened.
    let older = rzTrail(subject, pick, i + STRIDE).y;
    let newer = rzTrail(subject, pick, i - STRIDE).y;
    if (older - s.y < TOUCH_EPS) { continue; }   // was not descending
    if (s.y - newer > TOUCH_EPS) { continue; }   // still descending

    // Elongate along the direction of travel: a footprint is longer than it is
    // wide, and the step direction is the only orientation trail data carries.
    // (The foot's actual facing would need per-contact data — see the note above.)
    let travel = s.xz - rzTrail(subject, pick, i + STRIDE).xz;
    var axis = vec2f(0.0, 1.0);
    if (length(travel) > 1e-4) { axis = normalize(travel); }
    let rel = p.xz - s.xz;
    let local = vec2f(dot(rel, axis) / ELONGATE, dot(rel, vec2f(-axis.y, axis.x)));
    let dist = length(local);
    if (dist > RADIUS) { continue; }

    // Compact support: zero at the rim, so the cull leaves no hard edge.
    let shape = 1.0 - smoothstep(RADIUS * (1.0 - EDGE), RADIUS, dist);
    let age = 1.0 - clamp(s.w / FADE, 0.0, 1.0);
    acc = max(acc, shape * age * age);
  }
  return acc;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  // Nothing was drawn here, so there is no floor to mark.
  if (depth >= FAR_CLAMP) { return vec4f(0.0); }
  let p = rzWorldPos(ray, depth);

  var acc = 0.0;
  for (var i = 0; i < rzSubjectCount(); i++) {
    let s = rzSubject(i);
    if (!s.valid) { continue; }
    // On the FLOOR, and only on the floor: xz alone describes a vertical
    // cylinder, which paints up the legs and everything else standing in it.
    let flat = 1.0 - smoothstep(FLATNESS * 0.5, FLATNESS, abs(p.y - s.root.y));
    if (flat <= 0.001) { continue; }
    acc = max(acc, markFor(i, 0, 2, p) * flat);
    acc = max(acc, markFor(i, 1, 3, p) * flat);
  }
  let heat = acc * STRENGTH;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Deep blue at the rim, cyan through the body, white-hot in the middle of a
  // fresh print — and the whole thing cools as it ages, because `acc` carries
  // the age fade into the intensity this reads.
  var rgb = mix(RIM_COLOR, GLOW_COLOR, smoothstep(0.04, 0.45, heat));
  rgb = mix(rgb, HOT_COLOR, smoothstep(0.55, 1.25, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}
